// Node: "Run Config"  (Code, Run Once for All Items)
// The single item every other node takes its bearings from.
//
// Emits: { run_id, triggered_by, as_of, supabase_url, periods: [...] }
//
// as_of is frozen HERE and used everywhere downstream. Nothing further down the
// graph calls new Date(): a run that takes two minutes must not compute
// "last 30 days" against two different todays, and a fixed as_of is also what
// makes a test run reproducible.

// ---- tunables -------------------------------------------------------------

// THE REPORTING REFERENCE DATE. Fixed by the KPI guide, not taken from the clock.
// All three sources cover January 2025 to June 2026, so a run anchored to the
// real today returns nothing at all and the dashboard looks broken while the
// workflow is working correctly. Change this only when the data does.
const REFERENCE_DATE = '2026-06-30';

const FISCAL_YEAR_START_MONTH = 1;   // 1 = January. YTD is wrong if this is wrong.

// start = end - N days, which is how the KPI guide defines them:
// "last 30 days" is 31 May - 30 June 2026, "last 90 days" is 1 April - 30 June.
// Both windows are therefore N+1 days inclusive. Matching the guide's stated
// dates matters more than any argument about off-by-one.
const ROLLING_WINDOWS = [
  { key: 'last_30_days', label: 'Last 30 days', days: 30 },
  { key: 'last_90_days', label: 'Last 90 days', days: 90 },
];

// The one value that cannot be known ahead of time. Every HTTP node reads it
// from here rather than carrying its own copy, so pointing the workflow at a
// different Supabase project is a one-line change. Not a secret -- the project
// URL is public; the key lives in the n8n credential.
const SUPABASE_URL = 'https://<enter your project id>.supabase.co';

// ---------------------------------------------------------------------------

const input = $input.first()?.json ?? {};
const body = input.body ?? {};

// Which trigger fired. The three emit recognisably different payloads: the
// Webhook wraps everything in body/headers/query, the Schedule Trigger emits a
// timestamp, and the Manual Trigger emits an empty object. A caller can also
// state it outright, which is what the test harness does.
function detectTrigger() {
  if (body.triggered_by) return String(body.triggered_by);
  if (input.headers || input.body || input.query) return 'webhook';
  if (input.timestamp || input['Readable date']) return 'schedule';
  return 'manual';
}

// A v4 UUID without reaching for a module. n8n's Code sandbox does not reliably
// expose node:crypto, so this falls back rather than throwing on some hosts.
function uuid() {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
  });
}

const isIsoDate = (v) => /^\d{4}-\d{2}-\d{2}$/.test(String(v ?? ''));
const iso = (d) => d.toISOString().slice(0, 10);
const shift = (d, days) => {
  const out = new Date(d);
  out.setUTCDate(out.getUTCDate() + days);
  return out;
};

// as_of may be pinned by the caller. The harness and the messy-data tests rely
// on this: "last 30 days" against a moving today is not a fixture.
const asOfIso = isIsoDate(body.as_of) ? body.as_of : REFERENCE_DATE;
const asOf = new Date(asOfIso + 'T00:00:00Z');

const y = asOf.getUTCFullYear();

// Fiscal year start: this calendar year's, unless that is still ahead of us.
let fyStart = new Date(Date.UTC(y, FISCAL_YEAR_START_MONTH - 1, 1));
if (fyStart > asOf) fyStart = new Date(Date.UTC(y - 1, FISCAL_YEAR_START_MONTH - 1, 1));

const periods = ROLLING_WINDOWS.map((w) => ({
  key: w.key,
  label: w.label,
  start: iso(shift(asOf, -w.days)),
  end: asOfIso,
}));

periods.push({ key: 'ytd', label: 'Year to date', start: iso(fyStart), end: asOfIso });

// The fourth period the KPI guide requires. Only present when the caller asked
// for one -- the dashboard's custom range picker POSTs custom_start/custom_end
// to the webhook, and the run comes back with a `custom` period alongside the
// three standing ones. Reversed dates are corrected rather than rejected, since
// a swapped pair is a slip, not an instruction.
if (isIsoDate(body.custom_start) && isIsoDate(body.custom_end)) {
  const a = body.custom_start;
  const b = body.custom_end;
  const start = a <= b ? a : b;
  const end = a <= b ? b : a;
  periods.push({ key: 'custom', label: `${start} to ${end}`, start, end });
}

const out = [];

out.push({
  json: {
    run_id: uuid(),
    triggered_by: detectTrigger(),
    as_of: asOfIso,
    supabase_url: SUPABASE_URL,
    periods,
  },
});

return out;

// Shared helpers, prepended by build.js to every Code node that needs them.
// Not an n8n node on its own -- it declares no items and returns nothing.
//
// Everything here follows one rule: a value that cannot be trusted becomes
// null and is reported, never guessed at. parseDate does not "do its best"
// with 2026-13-45; it returns null and the caller flags the record.

const PLACEHOLDERS = new Set([
  '', '-', '--', 'n/a', 'na', 'none', 'null', 'nil', 'unknown', 'tbc', 'tbd', '#n/a',
]);

/** Trimmed string, or null for blanks and the placeholder words people type
 *  into spreadsheets when they mean "I don't know". */
function norm(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  return PLACEHOLDERS.has(s.toLowerCase()) ? null : s;
}

/** Strict date parse -> 'YYYY-MM-DD' or null.
 *  Accepts ISO (with or without a time part), D/M/Y and D-M-Y. Rejects
 *  impossible calendar dates by round-tripping the components: 2026-13-45
 *  and 31/02/2026 both come back null rather than silently rolling over into
 *  the next month, which is what `new Date()` would do. */
function parseDate(v) {
  const s = norm(v);
  if (s === null) return null;

  let y, m, d;
  let match = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ].*)?$/);
  if (match) {
    [, y, m, d] = match;
  } else {
    match = s.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/);
    if (!match) return null;
    [, d, m, y] = match;          // day-first; see SETUP.md if your source is US-order
  }

  y = Number(y); m = Number(m); d = Number(d);
  if (m < 1 || m > 12 || d < 1 || d > 31) return null;

  const probe = new Date(Date.UTC(y, m - 1, d));
  if (probe.getUTCFullYear() !== y || probe.getUTCMonth() !== m - 1 || probe.getUTCDate() !== d) {
    return null;                  // 31 February and friends
  }
  return probe.toISOString().slice(0, 10);
}

/** Money -> number or null. Handles '$1,200', '1 200,50', '(450)' for negative,
 *  and a bare number that arrived as a JS number already. */
function parseAmount(v) {
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  const s = norm(v);
  if (s === null) return null;

  const negative = /^\(.*\)$/.test(s);
  let t = s.replace(/[()]/g, '').replace(/[^\d.,-]/g, '');
  if (t === '' || t === '-') return null;

  // Decide which separator is the decimal point by looking at the last one.
  const lastComma = t.lastIndexOf(',');
  const lastDot = t.lastIndexOf('.');
  if (lastComma > lastDot) {
    t = t.replace(/\./g, '').replace(',', '.');
  } else {
    t = t.replace(/,/g, '');
  }

  const n = Number(t);
  if (!Number.isFinite(n)) return null;
  return negative ? -n : n;
}

/** Inclusive window test on two 'YYYY-MM-DD' strings. String comparison is
 *  correct for ISO dates and avoids dragging a timezone into it. */
function inWindow(iso, start, end) {
  return iso !== null && iso >= start && iso <= end;
}

function daysBetween(fromIso, toIso) {
  if (!fromIso || !toIso) return null;
  const ms = Date.parse(toIso + 'T00:00:00Z') - Date.parse(fromIso + 'T00:00:00Z');
  return Math.round(ms / 86400000);
}

/** Division that refuses to invent a number. Returns null when the
 *  denominator is zero or missing -- an empty period must not read as 0%. */
function ratio(numerator, denominator) {
  if (denominator === null || denominator === undefined || Number(denominator) === 0) return null;
  return Number(numerator) / Number(denominator);
}

function mean(values) {
  const nums = values.filter((v) => typeof v === 'number' && Number.isFinite(v));
  if (nums.length === 0) return null;
  return nums.reduce((a, b) => a + b, 0) / nums.length;
}

function sum(values) {
  return values.reduce((a, b) => a + (typeof b === 'number' && Number.isFinite(b) ? b : 0), 0);
}

/** One metric row, shaped for the metrics table. Used ~30 times in the engine,
 *  so it is worth the four lines. */
function metric(domain, key, value, unit, denominator) {
  return {
    domain,
    metric_key: key,
    metric_value: (typeof value === 'number' && Number.isFinite(value)) ? value : null,
    metric_text: typeof value === 'string' ? value : null,
    unit,
    denominator: denominator === undefined ? null : denominator,
  };
}


// Node: "Normalise Sales"  (Code, Run Once for All Items)
// Google Sheets rows -> sales_leads rows, plus a data_quality_issues row for
// every field that could not be trusted.
//
// Emits ONE item carrying arrays, not one item per record: the Merge downstream
// stays legible with 3 items instead of 300, the Supabase write wants an array
// body anyway, and the counts have to be computed where the source rows are
// still in scope.
//
// Nothing is dropped and nothing is repaired. A row with a broken date is stored
// with is_countable = false and named in the issues list; silently skipping it
// is how a dashboard ends up confidently wrong.

// --- source contract ------------------------------------------------------
//
// The ONLY place the sheet's column names appear. Tab `Sheet1` of
// "Week 2 Sales Source Data".

const FIELD_MAP = {
  lead_date:       'date',
  lead_id:         'lead_id',
  status:          'status',
  deal_amount:     'deal_amount',
  marketing_spend: 'marketing_spend',
  lead_source:     'lead_source',
};

// The four statuses the source actually uses. Compared lowercased and trimmed.
const WON = ['closed won'];
const LOST = ['closed lost'];
const OPEN = ['qualified', 'proposal sent'];        // the KPI guide's pipeline definition

// --- did the source itself fail? ------------------------------------------
//
// The source node is On Error -> Continue, so a 500 arrives here as a single
// item carrying `error` and nothing else. Treating it as a record would invent
// one bogus row and, worse, report the source as healthy. A failed source is
// reported as failed; that is a different fact from a quiet month.

const inputItems = $input.all();
const failed = inputItems.length > 0
  && inputItems.every((it) => (it.json || {}).error !== undefined);

if (failed) {
  const rawError = (inputItems[0].json || {}).error;
  const message = typeof rawError === 'string'
    ? rawError
    : (rawError && rawError.message) || 'Source node reported an error.';
  return [{
    json: {
      source: 'sales',
      failed: true,
      error: message,
      rows: [],
      issues: [],
      counts: { fetched: 0, kept: 0, excluded: 0 },
    },
  }];
}

const run = $('Run Config').first().json;

const rows = [];
const issues = [];
let fetched = 0;

for (const item of inputItems) {
  const j = item.json || {};
  fetched += 1;

  // The Sheets node supplies row_number. It is the only durable handle back to
  // the source row, so every issue and every stored record carries it.
  const ref = j.row_number === undefined ? null : String(j.row_number);
  const flags = [];

  const pick = (key) => j[FIELD_MAP[key]];

  const note = (type, detail) => {
    flags.push(type);
    issues.push({ run_id: run.run_id, source: 'sales', source_row_ref: ref, issue_type: type, detail });
  };

  const leadId = norm(pick('lead_id'));
  const statusRaw = norm(pick('status'));
  const status = statusRaw === null ? null : statusRaw.toLowerCase();
  const leadDate = parseDate(pick('lead_date'));
  const leadSource = norm(pick('lead_source'));

  const rawAmount = pick('deal_amount');
  const rawSpend = pick('marketing_spend');
  const dealAmount = parseAmount(rawAmount);
  const marketingSpend = parseAmount(rawSpend);

  // --- flag, do not repair ------------------------------------------------

  if (leadId === null) note('missing_identifier', 'lead_id is blank.');
  if (statusRaw === null) {
    note('missing_status', 'status is blank, so this lead cannot be counted as won, lost or open.');
  } else if (![...WON, ...LOST, ...OPEN].includes(status)) {
    note('unknown_status', `status "${statusRaw}" is not one of Closed Won, Closed Lost, Qualified, Proposal Sent.`);
  }

  if (leadDate === null && norm(pick('lead_date')) !== null) {
    note('invalid_date', `date "${String(rawAmount === undefined ? '' : pick('lead_date'))}" is not a real calendar date.`);
  } else if (leadDate === null) {
    note('missing_date', 'date is blank, so this lead falls into no reporting period.');
  }

  // deal_amount is legitimately 0 on a Closed Lost row -- that is a value, not a
  // gap. Only a blank or unparseable amount is a problem.
  if (dealAmount === null && norm(rawAmount) !== null) {
    note('invalid_amount', `deal_amount "${String(rawAmount)}" is not a number.`);
  } else if (dealAmount === null) {
    note('missing_amount', 'deal_amount is blank.');
  }

  if (marketingSpend === null && norm(rawSpend) !== null) {
    note('invalid_amount', `marketing_spend "${String(rawSpend)}" is not a number.`);
  } else if (marketingSpend === null) {
    note('missing_cost', 'marketing_spend is blank, so cost per lead may be understated.');
  }

  if (leadSource === null) note('missing_lead_source', 'lead_source is blank; revenue by lead source cannot attribute this row.');

  const isEmptyRow = leadId === null && statusRaw === null && leadDate === null && dealAmount === null;
  if (isEmptyRow) note('empty_record', 'Row carries no lead id, status, date or amount.');

  const isWon = status === null ? null : WON.includes(status);
  const isLost = status === null ? null : LOST.includes(status);
  const isOpen = status === null ? null : OPEN.includes(status);

  // is_countable gates VALUE metrics. An uncountable row is still stored, still
  // counted in records_excluded, still shown on the dashboard.
  const isCountable = !isEmptyRow && leadDate !== null && statusRaw !== null;

  rows.push({
    run_id: run.run_id,
    source_row_ref: ref,
    lead_id: leadId,
    lead_date: leadDate,
    status: statusRaw,
    deal_amount: dealAmount,
    marketing_spend: marketingSpend,
    lead_source: leadSource,
    is_won: isWon,
    is_lost: isLost,
    is_open: isOpen,
    quality_flags: flags,
    is_countable: isCountable,
  });
}

const out = [];

out.push({
  json: {
    source: 'sales',
    failed: false,
    rows,
    issues,
    counts: {
      fetched,
      kept: rows.length,
      excluded: rows.filter((r) => !r.is_countable).length,
    },
  },
});

return out;

// Shared helpers, prepended by build.js to every Code node that needs them.
// Not an n8n node on its own -- it declares no items and returns nothing.
//
// Everything here follows one rule: a value that cannot be trusted becomes
