// Node: "Normalise Delivery"  (Code, Run Once for All Items)
// Airtable records -> delivery_projects rows, plus data_quality_issues.
// Same contract as Normalise Sales: one item out, carrying arrays.

// --- source contract ------------------------------------------------------
//
// Base "Week 2 Project Delivery Source", table `Projects`.

const FIELD_MAP = {
  project_id:     'project_id',
  project_name:   'project_name',
  team:           'team',
  owner:          'owner',
  kickoff_date:   'kickoff_date',
  due_date:       'due_date',
  completed_date: 'completed_date',
  status:         'status',
  budgeted_cost:  'budgeted_cost',
  actual_cost:    'actual_cost',
};

const COMPLETED = ['completed'];
const BLOCKED = ['blocked'];
const IN_PROGRESS = ['in progress'];

// --- did the source itself fail? ------------------------------------------

const inputItems = $input.all();
const failed = inputItems.length > 0
  && inputItems.every((it) => (it.json || {}).error !== undefined);

if (failed) {
  const rawError = (inputItems[0].json || {}).error;
  const message = typeof rawError === 'string'
    ? rawError
    : (rawError && rawError.message) || 'Source node reported an error.';
  return [{
    json: {
      source: 'delivery',
      failed: true,
      error: message,
      rows: [],
      issues: [],
      counts: { fetched: 0, kept: 0, excluded: 0 },
    },
  }];
}

const run = $('Run Config').first().json;

const rows = [];
const issues = [];
let fetched = 0;

for (const item of inputItems) {
  const j = item.json || {};
  fetched += 1;

  // The Airtable node has shipped both shapes: fields nested under `fields`, and
  // fields flattened onto json alongside `id`. Accept either rather than pinning
  // to whichever this instance happens to return today.
  const f = (j.fields && typeof j.fields === 'object') ? j.fields : j;
  const ref = norm(j.id) || null;
  const flags = [];

  const pick = (key) => f[FIELD_MAP[key]];

  const note = (type, detail) => {
    flags.push(type);
    issues.push({ run_id: run.run_id, source: 'delivery', source_row_ref: ref, issue_type: type, detail });
  };

  const projectId = norm(pick('project_id'));
  const statusRaw = norm(pick('status'));
  const status = statusRaw === null ? null : statusRaw.toLowerCase();
  const team = norm(pick('team'));

  const kickoffDate = parseDate(pick('kickoff_date'));
  const dueDate = parseDate(pick('due_date'));
  const completedDate = parseDate(pick('completed_date'));

  const budgeted = parseAmount(pick('budgeted_cost'));
  const actual = parseAmount(pick('actual_cost'));

  if (projectId === null) note('missing_identifier', 'project_id is blank.');
  if (statusRaw === null) {
    note('missing_status', 'status is blank, so this project cannot be counted as active, blocked or completed.');
  } else if (![...COMPLETED, ...BLOCKED, ...IN_PROGRESS].includes(status)) {
    note('unknown_status', `status "${statusRaw}" is not one of Completed, In Progress, Blocked.`);
  }
  if (team === null) note('missing_team', 'team is blank; delivery load by team cannot attribute this project.');

  if (kickoffDate === null && norm(pick('kickoff_date')) !== null) {
    note('invalid_date', `kickoff_date "${String(pick('kickoff_date'))}" is not a real calendar date.`);
  }
  // The KPI guide names these three explicitly: keep the record, add a warning.
  if (dueDate === null) {
    note(norm(pick('due_date')) === null ? 'missing_date' : 'invalid_date',
      'due_date is blank or invalid, so this project cannot be judged on time or late.');
  }
  const isCompleted = status === null ? null : COMPLETED.includes(status);
  if (isCompleted === true && completedDate === null) {
    note(norm(pick('completed_date')) === null ? 'missing_date' : 'invalid_date',
      'status is Completed but completed_date is blank or invalid, so this completion falls into no period.');
  }
  if (completedDate === null && norm(pick('completed_date')) !== null) {
    note('invalid_date', `completed_date "${String(pick('completed_date'))}" is not a real calendar date.`);
  }

  if (budgeted === null) {
    note(norm(pick('budgeted_cost')) === null ? 'missing_cost' : 'invalid_amount',
      'budgeted_cost is blank or invalid, so budget variance excludes this project.');
  }
  if (actual === null) {
    note(norm(pick('actual_cost')) === null ? 'missing_cost' : 'invalid_amount',
      'actual_cost is blank or invalid, so budget variance excludes this project.');
  }

  // A record that contradicts itself: report it, do not pick a winner.
  if (completedDate && kickoffDate && completedDate < kickoffDate) {
    note('inconsistent_dates', `completed_date ${completedDate} is before kickoff_date ${kickoffDate}.`);
  }

  const isBlocked = status === null ? null : BLOCKED.includes(status);
  const isInProgress = status === null ? null : IN_PROGRESS.includes(status);

  const isCountable = projectId !== null && statusRaw !== null;

  rows.push({
    run_id: run.run_id,
    source_row_ref: ref,
    project_id: projectId,
    project_name: norm(pick('project_name')),
    team,
    owner: norm(pick('owner')),
    kickoff_date: kickoffDate,
    due_date: dueDate,
    completed_date: completedDate,
    status: statusRaw,
    budgeted_cost: budgeted,
    actual_cost: actual,
    is_completed: isCompleted,
    is_blocked: isBlocked,
    is_in_progress: isInProgress,
    quality_flags: flags,
    is_countable: isCountable,
  });
}

const out = [];

out.push({
  json: {
    source: 'delivery',
    failed: false,
    rows,
    issues,
    counts: {
      fetched,
      kept: rows.length,
      excluded: rows.filter((r) => !r.is_countable).length,
    },
  },
});

return out;

// Shared helpers, prepended by build.js to every Code node that needs them.
// Not an n8n node on its own -- it declares no items and returns nothing.
//
// Everything here follows one rule: a value that cannot be trusted becomes
// null and is reported, never guessed at. parseDate does not "do its best"
// with 2026-13-45; it returns null and the caller flags the record.

const PLACEHOLDERS = new Set([
  '', '-', '--', 'n/a', 'na', 'none', 'null', 'nil', 'unknown', 'tbc', 'tbd', '#n/a',
]);

/** Trimmed string, or null for blanks and the placeholder words people type
 *  into spreadsheets when they mean "I don't know". */
function norm(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  return PLACEHOLDERS.has(s.toLowerCase()) ? null : s;
}

/** Strict date parse -> 'YYYY-MM-DD' or null.
 *  Accepts ISO (with or without a time part), D/M/Y and D-M-Y. Rejects
 *  impossible calendar dates by round-tripping the components: 2026-13-45
 *  and 31/02/2026 both come back null rather than silently rolling over into
 *  the next month, which is what `new Date()` would do. */
function parseDate(v) {
  const s = norm(v);
  if (s === null) return null;

  let y, m, d;
  let match = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ].*)?$/);
  if (match) {
    [, y, m, d] = match;
  } else {
    match = s.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/);
    if (!match) return null;
    [, d, m, y] = match;          // day-first; see SETUP.md if your source is US-order
  }

  y = Number(y); m = Number(m); d = Number(d);
  if (m < 1 || m > 12 || d < 1 || d > 31) return null;

  const probe = new Date(Date.UTC(y, m - 1, d));
  if (probe.getUTCFullYear() !== y || probe.getUTCMonth() !== m - 1 || probe.getUTCDate() !== d) {
    return null;                  // 31 February and friends
  }
  return probe.toISOString().slice(0, 10);
}

/** Money -> number or null. Handles '$1,200', '1 200,50', '(450)' for negative,
 *  and a bare number that arrived as a JS number already. */
function parseAmount(v) {
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  const s = norm(v);
  if (s === null) return null;

  const negative = /^\(.*\)$/.test(s);
  let t = s.replace(/[()]/g, '').replace(/[^\d.,-]/g, '');
  if (t === '' || t === '-') return null;

  // Decide which separator is the decimal point by looking at the last one.
  const lastComma = t.lastIndexOf(',');
  const lastDot = t.lastIndexOf('.');
  if (lastComma > lastDot) {
    t = t.replace(/\./g, '').replace(',', '.');
  } else {
    t = t.replace(/,/g, '');
  }

  const n = Number(t);
  if (!Number.isFinite(n)) return null;
  return negative ? -n : n;
}

/** Inclusive window test on two 'YYYY-MM-DD' strings. String comparison is
 *  correct for ISO dates and avoids dragging a timezone into it. */
function inWindow(iso, start, end) {
  return iso !== null && iso >= start && iso <= end;
}

function daysBetween(fromIso, toIso) {
  if (!fromIso || !toIso) return null;
  const ms = Date.parse(toIso + 'T00:00:00Z') - Date.parse(fromIso + 'T00:00:00Z');
  return Math.round(ms / 86400000);
}

/** Division that refuses to invent a number. Returns null when the
 *  denominator is zero or missing -- an empty period must not read as 0%. */
function ratio(numerator, denominator) {
  if (denominator === null || denominator === undefined || Number(denominator) === 0) return null;
  return Number(numerator) / Number(denominator);
}

function mean(values) {
  const nums = values.filter((v) => typeof v === 'number' && Number.isFinite(v));
  if (nums.length === 0) return null;
  return nums.reduce((a, b) => a + b, 0) / nums.length;
}

function sum(values) {
  return values.reduce((a, b) => a + (typeof b === 'number' && Number.isFinite(b) ? b : 0), 0);
}

/** One metric row, shaped for the metrics table. Used ~30 times in the engine,
 *  so it is worth the four lines. */
function metric(domain, key, value, unit, denominator) {
  return {
    domain,
    metric_key: key,
    metric_value: (typeof value === 'number' && Number.isFinite(value)) ? value : null,
    metric_text: typeof value === 'string' ? value : null,
    unit,
    denominator: denominator === undefined ? null : denominator,
  };
}


// Node: "Normalise People"  (Code, Run Once for All Items)
// People Ops API records -> people_records rows, plus data_quality_issues.
//
// The API returns an envelope, not a bare array:
//   { source, record_count, total_available_records, query, schema, records: [...] }
// so the HTTP Request node hands this one item, not one item per employee. The
// unwrap below also accepts a bare array and the data/results shapes, because
// which one an endpoint returns is not something to discover on submission day.

// --- source contract ------------------------------------------------------

const FIELD_MAP = {
  employee_id:         'employee_id',
  department:          'department',
  role:                'role',
  application_date:    'application_date',
  offer_accepted_date: 'offer_accepted_date',
  start_date:          'start_date',
  exit_date:           'exit_date',
  status:              'status',
};

// Declared, not inferred. A department with no records in the selected period
// has to be reportable, and you cannot notice the absence of something you only
// ever learned about from the data itself.
const EXPECTED_DEPARTMENTS = ['Sales', 'Delivery', 'Engineering', 'People Ops'];

// A Candidate has applied but not started. They are not headcount and never were.
const STATUSES = ['active', 'exited', 'candidate'];

// --- did the source itself fail? ------------------------------------------

const inputItems = $input.all();
const failed = inputItems.length > 0
  && inputItems.every((it) => (it.json || {}).error !== undefined);

if (failed) {
  const rawError = (inputItems[0].json || {}).error;
  const message = typeof rawError === 'string'
    ? rawError
    : (rawError && rawError.message) || 'Source node reported an error.';
  return [{
    json: {
      source: 'people',
      failed: true,
      error: message,
      rows: [],
      issues: [],
      expected_departments: EXPECTED_DEPARTMENTS,
      counts: { fetched: 0, kept: 0, excluded: 0 },
    },
  }];
}

const run = $('Run Config').first().json;

// --- unwrap ---------------------------------------------------------------

const raw = [];
let reportedTotal = null;
let queryWasFiltered = false;

for (const item of inputItems) {
  const j = item.json || {};
  if (j.total_available_records !== undefined) reportedTotal = j.total_available_records;
  // total_available_records is the size of the WHOLE population, so it only
  // tells us about truncation when the request asked for all of it.
  if (j.query && typeof j.query === 'object') {
    queryWasFiltered = Object.values(j.query).some((v) => v !== null && v !== '');
  }

  const wrapped = Array.isArray(j) ? j
    : Array.isArray(j.records) ? j.records
      : Array.isArray(j.data) ? j.data
        : Array.isArray(j.results) ? j.results
          : null;
  if (wrapped) {
    for (const r of wrapped) raw.push(r || {});
  } else if (j.employee_id !== undefined || j.application_date !== undefined) {
    raw.push(j);          // already split into one item per employee
  }
}

const rows = [];
const issues = [];
let fetched = 0;

for (let i = 0; i < raw.length; i++) {
  const j = raw[i] || {};
  fetched += 1;

  const pick = (key) => j[FIELD_MAP[key]];
  const ref = norm(pick('employee_id')) || `index_${i}`;
  const flags = [];

  const note = (type, detail) => {
    flags.push(type);
    issues.push({ run_id: run.run_id, source: 'people', source_row_ref: ref, issue_type: type, detail });
  };

  const employeeId = norm(pick('employee_id'));
  const department = norm(pick('department'));
  const statusRaw = norm(pick('status'));
  const status = statusRaw === null ? null : statusRaw.toLowerCase();

  const applicationDate = parseDate(pick('application_date'));
  const offerAcceptedDate = parseDate(pick('offer_accepted_date'));
  const startDate = parseDate(pick('start_date'));
  const exitDate = parseDate(pick('exit_date'));

  if (employeeId === null) note('missing_identifier', 'employee_id is blank; addressed by position instead.');
  if (department === null) note('missing_department', 'department is blank; headcount by department cannot attribute this person.');
  if (statusRaw === null) {
    note('missing_status', 'status is blank, so this person cannot be counted in headcount.');
  } else if (!STATUSES.includes(status)) {
    note('unknown_status', `status "${statusRaw}" is not one of Active, Exited, Candidate.`);
  }

  if (applicationDate === null) {
    note(norm(pick('application_date')) === null ? 'missing_date' : 'invalid_date',
      'application_date is blank or invalid, so time to hire and offer acceptance time exclude this record.');
  }
  if (startDate === null && norm(pick('start_date')) !== null) {
    note('invalid_date', `start_date "${String(pick('start_date'))}" is not a real calendar date.`);
  }
  if (exitDate === null && norm(pick('exit_date')) !== null) {
    note('invalid_date', `exit_date "${String(pick('exit_date'))}" is not a real calendar date.`);
  }
  if (offerAcceptedDate === null && norm(pick('offer_accepted_date')) !== null) {
    note('invalid_date', `offer_accepted_date "${String(pick('offer_accepted_date'))}" is not a real calendar date.`);
  }

  // The two contradictions that quietly distort People Ops numbers.
  if (status === 'exited' && exitDate === null) {
    note('missing_exit_date', 'status is Exited but exit_date is blank, so this exit cannot be dated into a period.');
  }
  if (status === 'active' && startDate === null) {
    note('missing_start_date', 'status is Active but start_date is blank, so this person cannot be counted in headcount.');
  }
  if (startDate && exitDate && exitDate < startDate) {
    note('inconsistent_dates', `exit_date ${exitDate} is before start_date ${startDate}.`);
  }

  const isCountable = statusRaw !== null;

  rows.push({
    run_id: run.run_id,
    source_row_ref: ref,
    employee_id: employeeId,
    department,
    role: norm(pick('role')),
    status: statusRaw,
    application_date: applicationDate,
    offer_accepted_date: offerAcceptedDate,
    start_date: startDate,
    exit_date: exitDate,
    quality_flags: flags,
    is_countable: isCountable,
  });
}

// The endpoint reports how many records exist in total. If we asked for all of
// them and received fewer, we are looking at a truncated report, and saying so
// beats quietly under-reporting every headcount on the dashboard.
if (reportedTotal !== null && !queryWasFiltered && Number(reportedTotal) !== fetched) {
  issues.push({
    run_id: run.run_id,
    source: 'people',
    source_row_ref: null,
    issue_type: 'truncated_response',
    detail: `API reports ${reportedTotal} available records but ${fetched} were received.`,
  });
}

const out = [];

out.push({
  json: {
    source: 'people',
    failed: false,
    rows,
    issues,
    expected_departments: EXPECTED_DEPARTMENTS,
    counts: {
      fetched,
      kept: rows.length,
      excluded: rows.filter((r) => !r.is_countable).length,
    },
  },
});

return out;

// Node: "Assemble Facts"  (Code, Run Once for All Items)
// The convergence point. Three source branches arrive as three items; one item
// leaves, holding every cleaned record, every quality issue, and the counts.
//
// A source whose node failed still arrives here, because each source node is set
// to On Error -> Continue. It arrives as an error item with no rows, and that is
// recorded as a failed source rather than as a department that had a quiet month.
// The difference matters: one is a data problem, the other is a business fact,
// and Claude is told which it is looking at.

const run = $('Run Config').first().json;

const facts = { sales: [], delivery: [], people: [] };
const issues = [];
const sourceCounts = {};
const sourcesFailed = [];
let expectedDepartments = [];

for (const item of $input.all()) {
  const j = item.json || {};

  // A normaliser that saw an upstream failure says so outright with failed:true.
  // A raw n8n error item that reached here some other way carries `error` and no
  // source name. Both are the same fact: this source did not report.
  if (j.failed === true || j.error || !j.source) {
    const rawError = j.error;
    const message = typeof rawError === 'string'
      ? rawError
      : (rawError && rawError.message) || 'Source node returned no data.';
    sourcesFailed.push({ source: j.source || 'unknown', message });
    continue;
  }

  facts[j.source] = Array.isArray(j.rows) ? j.rows : [];
  for (const issue of (Array.isArray(j.issues) ? j.issues : [])) issues.push(issue);
  sourceCounts[j.source] = j.counts || { fetched: 0, kept: 0, excluded: 0 };

  // The declared department list travels with the people branch. It is declared
  // rather than inferred: a department with no records has to be reportable, and
  // you cannot notice the absence of something you only learned from the data.
  if (j.source === 'people' && Array.isArray(j.expected_departments)) {
    expectedDepartments = j.expected_departments;
  }
}

// A source that never reported at all still needs a zeroed entry, otherwise the
// summary silently omits it and "no sales data" reads as "no sales".
for (const source of ['sales', 'delivery', 'people']) {
  if (!sourceCounts[source]) {
    sourceCounts[source] = { fetched: 0, kept: 0, excluded: 0 };
    if (!sourcesFailed.some((f) => f.source === source)) {
      sourcesFailed.push({ source, message: 'Source produced no items.' });
    }
  }
}

const out = [];

out.push({
  json: {
    run_id: run.run_id,
    as_of: run.as_of,
    triggered_by: run.triggered_by,
    periods: run.periods,
    facts,
    issues,
    source_counts: sourceCounts,
    sources_failed: sourcesFailed.map((f) => f.source),
    sources_failed_detail: sourcesFailed,
    // departments_with_no_data is NOT computed here: it is per-period, and a
    // department can be quiet for 30 days and busy year to date. The metric
    // engine derives it inside the loop.
    expected_departments: expectedDepartments,
    totals: {
      fetched: Object.values(sourceCounts).reduce((a, c) => a + (c.fetched || 0), 0),
      kept: Object.values(sourceCounts).reduce((a, c) => a + (c.kept || 0), 0),
      excluded: Object.values(sourceCounts).reduce((a, c) => a + (c.excluded || 0), 0),
    },
  },
});

return out;

// Node: "Source Fingerprint"  (Code, Run Once for All Items)
// Hashes everything that determines this run's output.
//
// Two runs with the same fingerprint would produce byte-identical metrics and
// byte-identical insights, so the second one has nothing to add and can return
// the first instead. Most Refresh clicks land on unchanged sources; without
// this, each one spends a Claude call restating what is already on screen.
//
// WHAT GOES INTO THE HASH -- and why each part has to:
//   * as_of          -- moves every window
//   * the periods    -- a custom range changes what is computed, even though the
//                       source records are identical. Leave this out and asking
//                       for a custom window would be skipped and never computed.
//   * every normalised fact row, minus run_id, which differs by construction
//
// What is deliberately NOT in it: the trigger type, timestamps, and the issue
// list (which is derived from the rows and so already covered).

const facts = $('Assemble Facts').first().json;

// FNV-1a, twice with different offsets, concatenated. Not cryptographic -- it
// only has to make an accidental collision between two different data sets
// implausible, and 64 bits is far more than enough for that.
function fnv1a(str, seed) {
  let h = seed >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h;
}

function hash(str) {
  const a = fnv1a(str, 0x811c9dc5);
  const b = fnv1a(str, 0x9e3779b9);
  return a.toString(16).padStart(8, '0') + b.toString(16).padStart(8, '0');
}

// Keys are sorted so the hash cannot change just because a normaliser started
// emitting its fields in a different order.
function canonical(value) {
  if (value === null || value === undefined) return 'null';
  if (Array.isArray(value)) return '[' + value.map(canonical).join(',') + ']';
  if (typeof value === 'object') {
    return '{' + Object.keys(value).sort()
      .filter((k) => k !== 'run_id')
      .map((k) => k + ':' + canonical(value[k]))
      .join(',') + '}';
  }
  return String(value);
}

const material = canonical({
  as_of: facts.as_of,
  periods: (facts.periods || []).map((p) => [p.key, p.start, p.end]),
  sales: facts.facts.sales || [],
  delivery: facts.facts.delivery || [],
  people: facts.facts.people || [],
});

const out = [];

out.push({
  json: {
    run_id: facts.run_id,
    triggered_by: facts.triggered_by,
    source_fingerprint: hash(material),
    fingerprint_bytes: material.length,
  },
});

return out;

// Node: "Decide Skip"  (Code, Run Once for All Items)
// Reads the fingerprint lookup and decides whether this run has anything to add.
//
// Skip when: a completed run already carries this exact fingerprint, AND this
// run was not started by the schedule.
//
// The schedule never skips. Its whole purpose is to lay down a daily history
// point, and a history that omits the days nothing changed is not a history --
// it is a history with holes in exactly the places a reader would want to see
// stability. Refresh and the custom-range button are the ones worth
// short-circuiting: they are someone waiting at a screen.

const fingerprint = $('Source Fingerprint').first().json;
const facts = $('Assemble Facts').first().json;

// Rows the lookup returned, if any. The node is alwaysOutputData, so an empty
// result arrives as a single item with no run_id rather than as zero items.
const matches = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.run_id) matches.push(j);
}

const match = matches[0] || null;
const isScheduled = facts.triggered_by === 'schedule';
const skip = Boolean(match) && !isScheduled;

const reason = skip
  ? `Sources, reference date and period windows are unchanged since the run of ${match.started_at}. Recomputing could only produce the same numbers.`
  : match
    ? 'Fingerprint matches an earlier run, but this run is scheduled and the daily history point is the point of it.'
    : 'No completed run carries this fingerprint, so something has changed.';

const out = [];

out.push({
  json: {
    run_id: facts.run_id,
    triggered_by: facts.triggered_by,
    source_fingerprint: fingerprint.source_fingerprint,
    skip_run: skip,
    matched_run_id: match ? match.run_id : null,
    matched_started_at: match ? match.started_at : null,
    reason,
  },
});

return out;

// Node: "Build Write Payloads"  (Code, Run Once for All Items)
// Shapes every array that gets POSTed to PostgREST, on one item, so each HTTP
// node's body is a single expression: {{ JSON.stringify($json.sales_rows) }}.
//
// One POST with an array body per table, not one POST per record. n8n's Supabase
// node inserts item by item; nine hundred deals would be nine hundred HTTP calls.
//
// Also strips any internal underscore field. Posting an unknown column to
// PostgREST is a 400, and a stray "_flag" would take the whole run down.

const INTERNAL = /^_/;

function strip(row) {
  const clean = {};
  for (const [k, v] of Object.entries(row)) {
    if (!INTERNAL.test(k)) clean[k] = v;
  }
  return clean;
}

const facts = $('Assemble Facts').first().json;
const fingerprint = $('Source Fingerprint').first().json;

const out = [];

out.push({
  json: {
    run_id: facts.run_id,
    as_of: facts.as_of,
    // The runs row, written before the facts so a crash mid-write still leaves a
    // row saying a run started and never completed.
    run_row: {
      run_id: facts.run_id,
      status: 'running',
      triggered_by: facts.triggered_by,
      as_of: facts.as_of,
      source_counts: facts.source_counts,
      // Stamped now, so the next run can recognise unchanged sources and skip.
      source_fingerprint: fingerprint.source_fingerprint,
    },
    sales_rows: (facts.facts.sales || []).map(strip),
    delivery_rows: (facts.facts.delivery || []).map(strip),
    people_rows: (facts.facts.people || []).map(strip),
    issue_rows: facts.issues || [],
    counts: {
      sales: (facts.facts.sales || []).length,
      delivery: (facts.facts.delivery || []).length,
      people: (facts.facts.people || []).length,
      issues: (facts.issues || []).length,
    },
  },
});

return out;

