 *  correct for ISO dates and avoids dragging a timezone into it. */
function inWindow(iso, start, end) {
  return iso !== null && iso >= start && iso <= end;
}

function daysBetween(fromIso, toIso) {
  if (!fromIso || !toIso) return null;
  const ms = Date.parse(toIso + 'T00:00:00Z') - Date.parse(fromIso + 'T00:00:00Z');
  return Math.round(ms / 86400000);
}

/** Division that refuses to invent a number. Returns null when the
 *  denominator is zero or missing -- an empty period must not read as 0%. */
function ratio(numerator, denominator) {
  if (denominator === null || denominator === undefined || Number(denominator) === 0) return null;
  return Number(numerator) / Number(denominator);
}

function mean(values) {
  const nums = values.filter((v) => typeof v === 'number' && Number.isFinite(v));
  if (nums.length === 0) return null;
  return nums.reduce((a, b) => a + b, 0) / nums.length;
}

function sum(values) {
  return values.reduce((a, b) => a + (typeof b === 'number' && Number.isFinite(b) ? b : 0), 0);
}

/** One metric row, shaped for the metrics table. Used ~30 times in the engine,
 *  so it is worth the four lines. */
function metric(domain, key, value, unit, denominator) {
  return {
    domain,
    metric_key: key,
    metric_value: (typeof value === 'number' && Number.isFinite(value)) ? value : null,
    metric_text: typeof value === 'string' ? value : null,
    unit,
    denominator: denominator === undefined ? null : denominator,
  };
}


// Node: "Metric Engine"  (Code, Run Once for All Items)
// EVERY reporting period in one pass, each computed twice: once for the window,
// once for the equal-length window immediately before it.
//
// There is no loop around this node. There never needed to be one: the whole
// calculation is arithmetic over arrays already in memory, and computing four
// windows costs microseconds. The loop existed to give Claude one period at a
// time, and it made three model calls wait for each other -- about two thirds
// of a run's wall clock. Claude now gets all of them in a single call.
//
// The prior window is what makes the guide's directional questions answerable.
// "Did win rate improve, decline, or stay stable?" cannot be answered against
// the last RUN: run twice in ten minutes and the two windows overlap by 99%, so
// every metric is trivially identical and the only honest answer is "no
// movement". Compared against the preceding window of the same length, the
// question has a real answer.
//
// Pure arithmetic. No I/O, no clock, no randomness -- which is what lets
// test/harness.js assert the whole thing against hand-computed values.
//
// The facts come from Assemble Facts BY NAME -- $input here is the output of
// Fetch Previous Metrics, which is previous metric rows, not this run's records.

// --- tunables -------------------------------------------------------------

const NEAR_BUDGET = 0.9;

// --------------------------------------------------------------------------

const source = $('Assemble Facts').first().json;

const sales = source.facts.sales || [];
const delivery = source.facts.delivery || [];
const people = source.facts.people || [];

const salesCountable = sales.filter((r) => r.is_countable);
const deliveryCountable = delivery.filter((r) => r.is_countable);
const peopleCountable = people.filter((r) => r.is_countable);

const departments = source.expected_departments || [];

// ==========================================================================
// One window in, its metrics out. Called twice.
// ==========================================================================

function computeWindow(pStart, pEnd) {
  const m = [];
  const push = (domain, key, value, unit, denominator, group) => {
    m.push({
      domain,
      metric_key: key,
      group_key: group === undefined ? null : group,
      metric_value: (typeof value === 'number' && Number.isFinite(value)) ? value : null,
      metric_text: typeof value === 'string' ? value : null,
      unit,
      denominator: denominator === undefined ? null : denominator,
    });
  };

  // ---------------------------------------------------------------- SALES

  const inPeriod = salesCountable.filter((r) => inWindow(r.lead_date, pStart, pEnd));
  const won = inPeriod.filter((r) => r.is_won === true);
  const lost = inPeriod.filter((r) => r.is_lost === true);
  const open = inPeriod.filter((r) => r.is_open === true);

  const revenueWon = sum(won.map((r) => r.deal_amount));
  const pipelineValue = sum(open.map((r) => r.deal_amount));
  const closedTotal = won.length + lost.length;

  // marketing_spend is a MONTHLY figure repeated on every lead row in that
  // month. Summing the column multiplies the budget by the lead count, so cost
  // per lead comes out wrong by exactly the factor it divides by. One value per
  // month, pro-rated by the share of that month inside the window.
  const spendByMonth = {};
  for (const r of sales) {
    if (r.lead_date === null || r.marketing_spend === null) continue;
    const month = r.lead_date.slice(0, 7);
    if (spendByMonth[month] === undefined) spendByMonth[month] = r.marketing_spend;
    else if (spendByMonth[month] !== r.marketing_spend) {
      spendByMonth[month] = Math.max(spendByMonth[month], r.marketing_spend);
    }
  }
  const daysInMonth = (month) => {
    const [y, mo] = month.split('-').map(Number);
    return new Date(Date.UTC(y, mo, 0)).getUTCDate();
  };
  let marketingSpend = 0;
  let monthsCovered = 0;
  for (const [month, spend] of Object.entries(spendByMonth)) {
    const mStart = month + '-01';
    const mEnd = month + '-' + String(daysInMonth(month)).padStart(2, '0');
    const oStart = mStart > pStart ? mStart : pStart;
    const oEnd = mEnd < pEnd ? mEnd : pEnd;
    if (oStart > oEnd) continue;
    marketingSpend += spend * ((daysBetween(oStart, oEnd) + 1) / daysInMonth(month));
    monthsCovered += 1;
  }
  marketingSpend = Math.round(marketingSpend * 100) / 100;

  push('sales', 'total_leads', inPeriod.length, 'count');
  push('sales', 'closed_won_deals', won.length, 'count');
  push('sales', 'closed_lost_deals', lost.length, 'count');
  push('sales', 'pipeline_value', pipelineValue, 'currency', open.length);
  push('sales', 'revenue_won', revenueWon, 'currency', won.length);
  push('sales', 'win_rate', ratio(won.length, closedTotal), 'percent', closedTotal);
  push('sales', 'marketing_spend', marketingSpend, 'currency', monthsCovered);
  push('sales', 'cost_per_lead', ratio(marketingSpend, inPeriod.length), 'currency', inPeriod.length);
  // Revenue per unit of spend: the "is marketing spend producing enough?"
  // question needs a ratio, not two numbers the reader has to divide.
  push('sales', 'revenue_per_marketing_dollar', ratio(revenueWon, marketingSpend), 'ratio', marketingSpend);
  push('sales', 'pipeline_per_marketing_dollar', ratio(pipelineValue, marketingSpend), 'ratio', marketingSpend);
  push('sales', 'marketing_spend_method',
    'One value per month, pro-rated by the share of each month inside the window.', 'text');

  const revenueBySource = {};
  for (const r of won) {
    const k = r.lead_source || 'not recorded';
    revenueBySource[k] = (revenueBySource[k] || 0) + (r.deal_amount || 0);
  }
  // A source with leads but no revenue reads 0, not absent: "we did not measure
  // it" and "it produced nothing" are different findings.
  for (const r of inPeriod) {
    const k = r.lead_source || 'not recorded';
    if (revenueBySource[k] === undefined) revenueBySource[k] = 0;
  }
  for (const [src, value] of Object.entries(revenueBySource)) {
    push('sales', 'revenue_by_lead_source', value, 'currency',
      inPeriod.filter((r) => (r.lead_source || 'not recorded') === src).length, src);
  }

  // ------------------------------------------------------------- DELIVERY

  const overlaps = (p) =>
    (p.kickoff_date === null || p.kickoff_date <= pEnd)
    && (p.completed_date === null || p.completed_date >= pStart);

  const active = deliveryCountable.filter(
    (p) => (p.is_in_progress === true || p.is_blocked === true) && overlaps(p));
  const blocked = deliveryCountable.filter((p) => p.is_blocked === true && overlaps(p));
  const completed = deliveryCountable.filter((p) => inWindow(p.completed_date, pStart, pEnd));

  const judgeable = completed.filter((p) => p.due_date !== null);
  const onTime = judgeable.filter((p) => p.completed_date <= p.due_date);
  const late = judgeable.filter((p) => p.completed_date > p.due_date);
  const delays = late.map((p) => daysBetween(p.due_date, p.completed_date)).filter((n) => n !== null);

  const costed = completed.filter((p) => p.budgeted_cost !== null && p.actual_cost !== null);
  const variance = sum(costed.map((p) => p.actual_cost)) - sum(costed.map((p) => p.budgeted_cost));
  const overBudget = costed.filter((p) => p.actual_cost > p.budgeted_cost);
  const nearBudget = active.filter(
    (p) => p.budgeted_cost > 0 && p.actual_cost !== null
      && (p.actual_cost / p.budgeted_cost) >= NEAR_BUDGET);

  push('delivery', 'active_projects', active.length, 'count');
  push('delivery', 'completed_projects', completed.length, 'count');
  push('delivery', 'blocked_projects', blocked.length, 'count', active.length);
  push('delivery', 'blocked_share_of_active', ratio(blocked.length, active.length), 'percent', active.length);
  push('delivery', 'on_time_completion_rate', ratio(onTime.length, judgeable.length), 'percent', judgeable.length);
  push('delivery', 'average_delay', mean(delays), 'days', late.length);
  push('delivery', 'budget_variance', costed.length ? variance : null, 'currency', costed.length);
  push('delivery', 'over_budget_projects', overBudget.length, 'count', costed.length);
  push('delivery', 'projects_near_budget', nearBudget.length, 'count', active.length);

  const byTeam = {};
  const byOwner = {};
  for (const p of [...active, ...completed]) {
    const t = p.team || 'not recorded';
    byTeam[t] = (byTeam[t] || 0) + 1;
    const o = p.owner || 'not recorded';
    byOwner[o] = (byOwner[o] || 0) + 1;
  }
  for (const [t, n] of Object.entries(byTeam)) push('delivery', 'delivery_load_by_team', n, 'count', undefined, t);
  // The KPI guide asks which teams OR OWNERS look overloaded. Answering half of
  // a question is not answering it.
  for (const [o, n] of Object.entries(byOwner)) push('delivery', 'delivery_load_by_owner', n, 'count', undefined, o);

  const blockedByTeam = {};
  for (const p of blocked) {
    const t = p.team || 'not recorded';
    blockedByTeam[t] = (blockedByTeam[t] || 0) + 1;
  }
  for (const [t, n] of Object.entries(blockedByTeam)) push('delivery', 'blocked_by_team', n, 'count', undefined, t);

  // --------------------------------------------------------------- PEOPLE

  const activeOn = (iso) => peopleCountable.filter(
    (r) => r.start_date !== null && r.start_date <= iso
      && (r.exit_date === null || r.exit_date > iso));

  const headcountStart = activeOn(pStart).length;
  const activeAtEnd = activeOn(pEnd);
  const headcountEnd = activeAtEnd.length;

  const applications = peopleCountable.filter((r) => inWindow(r.application_date, pStart, pEnd));
  const offers = peopleCountable.filter((r) => inWindow(r.offer_accepted_date, pStart, pEnd));
  const hires = peopleCountable.filter((r) => inWindow(r.start_date, pStart, pEnd));
  const exits = peopleCountable.filter((r) => inWindow(r.exit_date, pStart, pEnd));

  const ttl = hires.map((r) => daysBetween(r.application_date, r.start_date))
    .filter((n) => n !== null && n >= 0);
  const accept = offers.map((r) => daysBetween(r.application_date, r.offer_accepted_date))
    .filter((n) => n !== null && n >= 0);

  push('people', 'applications', applications.length, 'count');
  push('people', 'offers_accepted', offers.length, 'count');
  push('people', 'new_hires', hires.length, 'count');
  push('people', 'exits', exits.length, 'count');
  push('people', 'active_headcount', headcountEnd, 'count');
  push('people', 'active_headcount_start', headcountStart, 'count');
  push('people', 'net_headcount_change', headcountEnd - headcountStart, 'count');
  push('people', 'time_to_hire', mean(ttl), 'days', ttl.length);
  push('people', 'offer_acceptance_time', mean(accept), 'days', accept.length);
  // The guide's definition: exits over headcount at the START of the window,
  // not annualised. A rate the guide defines is not one to reinterpret.
  push('people', 'attrition_rate', ratio(exits.length, headcountStart), 'percent', headcountStart);

  const hcByDept = {};
  const exitsByDept = {};
  for (const d of departments) { hcByDept[d] = 0; exitsByDept[d] = 0; }
  for (const r of activeAtEnd) {
    const d = r.department || 'not recorded';
    hcByDept[d] = (hcByDept[d] || 0) + 1;
  }
  for (const r of exits) {
    const d = r.department || 'not recorded';
    exitsByDept[d] = (exitsByDept[d] || 0) + 1;
  }
  for (const [d, n] of Object.entries(hcByDept)) push('people', 'headcount_by_department', n, 'count', undefined, d);
  for (const [d, n] of Object.entries(exitsByDept)) push('people', 'exits_by_department', n, 'count', undefined, d);

  // Departments with no activity in THIS window, computed per window because a
  // department can be quiet for 30 days and busy year to date.
  const touched = (r) =>
    inWindow(r.application_date, pStart, pEnd) || inWindow(r.offer_accepted_date, pStart, pEnd)
    || inWindow(r.start_date, pStart, pEnd) || inWindow(r.exit_date, pStart, pEnd);
  const seen = new Set();
  for (const r of peopleCountable) {
    if (r.department && (touched(r) || activeAtEnd.includes(r))) seen.add(r.department);
  }
  const noData = departments.filter((d) => !seen.has(d));

  return { metrics: m, departments_with_no_data: noData };
}

// ==========================================================================
// Every period, plus the equal-length window immediately before each
// ==========================================================================

const shiftDays = (iso, n) => {
  const d = new Date(iso + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};

const keyOf = (r) => r.metric_key + '|' + (r.group_key === null ? '' : r.group_key);

// --- data quality: about the fetch, so it is computed once -----------------

const issuesBySource = { sales: {}, delivery: {}, people: {} };
for (const issue of source.issues || []) {
  const bucket = issuesBySource[issue.source] || (issuesBySource[issue.source] = {});
  bucket[issue.issue_type] = (bucket[issue.issue_type] || 0) + 1;
}

const skipped = {
  sales: sales.filter((r) => !r.is_countable).length,
  delivery: delivery.filter((r) => !r.is_countable).length,
  people: people.filter((r) => !r.is_countable).length,
};

// --------------------------------------------------------------------------

const allRows = [];
const periodSummaries = [];

for (const period of source.periods) {
  const pStart = period.start;
  const pEnd = period.end;
  const periodDays = Math.max(1, daysBetween(pStart, pEnd) + 1);

  const priorEnd = shiftDays(pStart, -1);
  const priorStart = shiftDays(priorEnd, -(periodDays - 1));

  const current = computeWindow(pStart, pEnd);
  const prior = computeWindow(priorStart, priorEnd);

  const priorByKey = {};
  for (const r of prior.metrics) priorByKey[keyOf(r)] = r.metric_value;

  // Quality rows are emitted per period because departments_with_no_data is a
  // property of the window: a department can be quiet for 30 days and busy year
  // to date.
  const quality = [];
  const qpush = (key, value, group) => quality.push({
    domain: 'quality', metric_key: key, group_key: group === undefined ? null : group,
    metric_value: typeof value === 'number' ? value : null,
    metric_text: typeof value === 'string' ? value : null,
    unit: 'count', denominator: null,
  });

  qpush('records_fetched', source.totals.fetched);
  qpush('records_kept', source.totals.kept);
  qpush('records_excluded', source.totals.excluded);
  for (const [src, n] of Object.entries(skipped)) qpush('records_skipped', n, src);
  for (const [src, types] of Object.entries(issuesBySource)) {
    for (const [type, n] of Object.entries(types)) qpush(`issue_${type}`, n, src);
  }
  for (const d of current.departments_with_no_data) {
    qpush(`no_data_${String(d).toLowerCase().replace(/[^a-z0-9]+/g, '_')}`, 1);
  }

  const rows = [...current.metrics, ...quality].map((row) => ({
    run_id: source.run_id,
    period_key: period.key,
    period_label: period.label,
    period_start: pStart,
    period_end: pEnd,
    prior_start: priorStart,
    prior_end: priorEnd,
    prior_value: row.domain === 'quality' ? null : (priorByKey[keyOf(row)] ?? null),
    ...row,
  }));

  for (const r of rows) allRows.push(r);

  periodSummaries.push({
    period_key: period.key,
    period_label: period.label,
    period_start: pStart,
    period_end: pEnd,
    period_days: periodDays,
    prior_start: priorStart,
    prior_end: priorEnd,
    metrics: rows,
    departments_with_no_data: current.departments_with_no_data,
  });
}

const out = [];

out.push({
  json: {
    run_id: source.run_id,
    as_of: source.as_of,
    period_keys: source.periods.map((p) => p.key),
    // Every metric row for every period, in one array: one batched write, not
    // one per period.
    metrics: allRows,
    periods: periodSummaries,
    quality: {
      records_fetched: source.totals.fetched,
      records_kept: source.totals.kept,
      records_excluded: source.totals.excluded,
      records_skipped: skipped,
      issues_by_source: issuesBySource,
      sources_failed: source.sources_failed || [],
    },
  },
});

return out;

// Node: "Prepare Claude Input"  (Code, Run Once for All Items)
// Turns EVERY period's metrics into a single prompt, and publishes the list of
// metric keys that Grounding Check will hold the answer to.
//
// One call, not one per period. The rules, the twelve questions and the data
// quality block are identical across periods and were previously sent three
// times over; only the metric blocks differ. Collapsing them removes two thirds
// of a run's wall clock.
//
// The cost, stated plainly: one call analysing three windows gives each less
// attention than a dedicated call does, and a failure now loses every period
// instead of one. The Claude node is set to retry for that reason, and Grounding
// Check writes a failed row per period so the dashboard degrades rather than
// going blank.
//
// The request is built HERE, not typed into the LLM node's parameter, so it can
// be diffed and unit-tested.
//
// What crosses into the model: computed metrics and a data quality summary.
// What does not: a single source record. That boundary is the whole design.

// --- what the executive summary must answer -------------------------------
//
// Straight from the KPI guide. Listing them as "questions your analysis should
// be able to answer" was not enough: the model spread the answers across risks,
// actions and warnings, and the summary ended up describing whichever metrics
// moved rather than answering what leadership asked. They are a contract now.

const SUMMARY_QUESTIONS = [
  'SALES',
  '  S1. Which lead sources produced the strongest revenue?',
  '  S2. Did win rate improve, decline, or stay roughly stable for this period?',
  '  S3. Is marketing spend producing enough pipeline or revenue?',
  '  S4. Are any records missing fields that affect sales calculations?',
  'PROJECT DELIVERY',
  '  D1. Which teams or owners appear overloaded?',
  '  D2. Are blocked projects increasing?',
  '  D3. Are projects finishing late or going over budget?',
  '  D4. Which delivery issue should the team address first?',
  'PEOPLE OPS',
  '  P1. Is hiring volume enough to support business activity?',
  '  P2. Are exits concentrated in any department?',
  '  P3. Is time to hire increasing or decreasing?',
  '  P4. Which People Ops data issues reduce confidence in the report?',
];

const RULES = [
  'You are an operations analyst writing for the leadership team of Koya Talent. Three teams report here: Sales, Project Delivery, and People Ops.',
  '',
  'You are given the calculated metrics for ONE reporting period and a data quality summary. Return an executive summary, operational risks or anomalies, recommended actions, and data quality warnings.',
  '',
  'THE EXECUTIVE SUMMARY IS A CONTRACT. It must answer all twelve questions below, in three short paragraphs -- one per department, in this order -- each opening with the department name in bold. Answer every question in its department\'s paragraph. Where a metric needed for an answer is absent or null, say that the question cannot be answered and why, rather than skipping it silently or substituting a different observation.',
  '',
  ...SUMMARY_QUESTIONS,
  '',
  'Rules, all binding:',
  '1. Use ONLY the metrics below. Every item in risks_and_anomalies and recommended_actions must cite the metric keys it rests on in its "metric_keys" field, and every key must appear in the ALLOWED list. A statement you cannot cite is a statement you must not make.',
  '2. Never estimate, extrapolate or invent a number you were not given. If something you want to say needs a metric that is absent, say it cannot be assessed.',
  '3. A metric shown as null was not computable, usually because its denominator was zero. Null is not zero. "No deals closed, so win rate cannot be computed" is right; "win rate fell to 0%" is not.',
  '4. Read the denominator before judging a rate. A 50% win rate over 4 closed deals is noise; over 400 it is a finding. Say which you are looking at.',
  '5. DIRECTION comes from "prior", which is the same metric over the equal-length window immediately BEFORE this one. That is the only comparison that answers S2, D2 and P3. Where prior is absent, say the direction cannot be established. Do not describe direction from a single observation.',
  '6. issues_by_source is already grouped by source. Attribute every issue to the source it is listed under and never to another. A flagged field is not the same thing as a skipped record: a record is skipped only when a missing field prevents it being counted at all, so the issue count is normally higher than records_skipped. Do not equate the two.',
  '7. If a department appears in departments_with_no_data, or a source in sources_failed, report it as a reporting gap and do NOT characterise that department\'s performance.',
  '8. If records_excluded is more than 10% of records_fetched, say in the executive summary that the figures are provisional.',
  '9. If there is nothing materially wrong, set no_material_issues to true and say so plainly. Do NOT pad risks or actions to look thorough. An empty risks list with a complete summary is a valid and useful answer. The executive summary must still answer all twelve questions.',
  '10. Be specific and short. No preamble, no restating the brief, no hedging that carries no information.',
  '',
  'Severity: "high" needs a decision this week, "medium" needs watching, "low" is worth knowing. Action priority uses the same scale.',
];

const DOMAIN_LABEL = {
  sales: 'SALES',
  delivery: 'PROJECT DELIVERY',
  people: 'PEOPLE OPS',
  quality: 'DATA QUALITY',
};

// --------------------------------------------------------------------------

const engine = $input.first().json;

// The previous RUN's values, used for exactly one thing per period: telling the
// model when this run repeats the last byte for byte, which usually means the
// sources have not moved rather than that the business has gone quiet.
// Direction of travel comes from `prior`, never from this.
const previousByKey = {};
try {
  for (const item of $('Fetch Previous Metrics').all()) {
    const p = item.json || {};
    if (p.metric_key) {
      previousByKey[p.period_key + '|' + p.metric_key + '|' + (p.group_key || '')] = p.metric_value;
    }
  }
} catch (e) { /* first run: nothing to compare, and that is not an error */ }

const keyOf = (r) => r.metric_key + '|' + (r.group_key === null ? '' : r.group_key);

const allowedKeys = [];
const periodBlocks = [];
const periodKeys = [];

for (const period of engine.periods) {
  periodKeys.push(period.period_key);

  const lines = { sales: [], delivery: [], people: [] };
  const grouped = {};
  let comparable = 0;
  let identical = 0;

  for (const row of period.metrics) {
    if (!allowedKeys.includes(row.metric_key)) allowedKeys.push(row.metric_key);

    if (row.domain !== 'quality') {
      const prev = previousByKey[period.period_key + '|' + keyOf(row)];
      if (prev !== undefined) {
        comparable += 1;
        if (Number(prev) === Number(row.metric_value)) identical += 1;
      }
    }

    if (row.domain === 'quality') continue;

    if (row.group_key) {
      const k = row.domain + '|' + row.metric_key;
      (grouped[k] || (grouped[k] = [])).push(row);
      continue;
    }

    const value = row.metric_value === null
      ? (row.metric_text === null ? 'null (not computable)' : row.metric_text)
      : String(Math.round(row.metric_value * 1000) / 1000);

    const bits = [`${row.metric_key} = ${value}`];
    if (row.unit && row.unit !== 'text') bits.push(`unit=${row.unit}`);
    if (row.denominator !== null && row.denominator !== undefined) bits.push(`over=${row.denominator}`);
    if (row.prior_value !== null && row.prior_value !== undefined) {
      bits.push(`prior=${Math.round(row.prior_value * 1000) / 1000}`);
    }
    lines[row.domain].push('  ' + bits.join(', '));
  }

  // Breakdowns render on one line each, largest first, so "which lead source was
  // strongest" and "which owner is overloaded" are answerable by reading.
  for (const [composite, rowsIn] of Object.entries(grouped)) {
    const [domain, key] = composite.split('|');
    const parts = rowsIn
      .slice()
      .sort((a, b) => (b.metric_value || 0) - (a.metric_value || 0))
      .map((r) => {
        const v = r.metric_value === null ? 'null' : r.metric_value;
        return (r.prior_value !== null && r.prior_value !== undefined)
          ? `${r.group_key}=${v} (prior ${r.prior_value})`
          : `${r.group_key}=${v}`;
      });
    lines[domain].push(`  ${key}: ${parts.join(', ')}`);
  }

  const identicalToPreviousRun = comparable > 0 && identical === comparable;

  const block = [
    '=========================================================================',
    `PERIOD "${period.period_key}" — ${period.period_label} (${period.period_start} to ${period.period_end}, ${period.period_days} days)`,
    `  prior window for direction: ${period.prior_start} to ${period.prior_end}`,
    `  departments with no data this window: ${JSON.stringify(period.departments_with_no_data)}`,
    identicalToPreviousRun
      ? '  NOTE: every metric here is identical to the last completed run of this same period. That usually means the sources have not changed, not that the business was flat. Mention it once as a reporting caveat, never as a performance finding.'
      : '',
    '',
  ].filter((x) => x !== '');

  for (const domain of ['sales', 'delivery', 'people']) {
    block.push(`${DOMAIN_LABEL[domain]} METRICS:`);
    block.push(lines[domain].length ? lines[domain].join('\n') : '  (none computed)');
    block.push('');
  }

  periodBlocks.push(block.join('\n'));
}

const q = engine.quality;
const excludedShare = q.records_fetched > 0
  ? Math.round((q.records_excluded / q.records_fetched) * 1000) / 10
  : 0;

const qualityBlock = [
  `  records_fetched = ${q.records_fetched}`,
  `  records_kept = ${q.records_kept}`,
  `  records_excluded = ${q.records_excluded} (${excludedShare}% of fetched)`,
  `  records_skipped_per_source = ${JSON.stringify(q.records_skipped)}`,
  `  issues_by_source = ${JSON.stringify(q.issues_by_source)}`,
  `  sources_failed = ${JSON.stringify(q.sources_failed)}`,
];

const prompt = [
  RULES.join('\n'),
  '',
  `Reference date for the whole report is ${engine.as_of}.`,
  '',
  `You are analysing ${periodKeys.length} reporting periods in one pass: ${periodKeys.join(', ')}.`,
  'Return ONE object per period, in the "periods" array, with its "period_key" set exactly as spelled above. Analyse each period on its own metrics; do not carry a finding from one window into another, and do not describe them as a group. A metric can be unremarkable over a year and alarming over thirty days.',
  '',
  'DATA QUALITY (one report, covering the whole fetch, so it applies to every period):',
  qualityBlock.join('\n'),
  '',
  periodBlocks.join('\n'),
  '=========================================================================',
  `ALLOWED metric_keys (cite only from this list, exactly as spelled): ${allowedKeys.join(', ')}`,
].join('\n');

const out = [];

out.push({
  json: {
    run_id: engine.run_id,
    period_keys: periodKeys,
    allowed_metric_keys: allowedKeys,
    prompt,
  },
});

return out;

