// Shared helpers, prepended by build.js to every Code node that needs them.
// Not an n8n node on its own -- it declares no items and returns nothing.
//
// Everything here follows one rule: a value that cannot be trusted becomes
// null and is reported, never guessed at. parseDate does not "do its best"
// with 2026-13-45; it returns null and the caller flags the record.

const PLACEHOLDERS = new Set([
  '', '-', '--', 'n/a', 'na', 'none', 'null', 'nil', 'unknown', 'tbc', 'tbd', '#n/a',
]);

/** Trimmed string, or null for blanks and the placeholder words people type
 *  into spreadsheets when they mean "I don't know". */
function norm(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  return PLACEHOLDERS.has(s.toLowerCase()) ? null : s;
}

/** Strict date parse -> 'YYYY-MM-DD' or null.
 *  Accepts ISO (with or without a time part), D/M/Y and D-M-Y. Rejects
 *  impossible calendar dates by round-tripping the components: 2026-13-45
 *  and 31/02/2026 both come back null rather than silently rolling over into
 *  the next month, which is what `new Date()` would do. */
function parseDate(v) {
  const s = norm(v);
  if (s === null) return null;

  let y, m, d;
  let match = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ].*)?$/);
  if (match) {
    [, y, m, d] = match;
  } else {
    match = s.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/);
    if (!match) return null;
    [, d, m, y] = match;          // day-first; see SETUP.md if your source is US-order
  }

  y = Number(y); m = Number(m); d = Number(d);
  if (m < 1 || m > 12 || d < 1 || d > 31) return null;

  const probe = new Date(Date.UTC(y, m - 1, d));
  if (probe.getUTCFullYear() !== y || probe.getUTCMonth() !== m - 1 || probe.getUTCDate() !== d) {
    return null;                  // 31 February and friends
  }
  return probe.toISOString().slice(0, 10);
}

/** Money -> number or null. Handles '$1,200', '1 200,50', '(450)' for negative,
 *  and a bare number that arrived as a JS number already. */
function parseAmount(v) {
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  const s = norm(v);
  if (s === null) return null;

  const negative = /^\(.*\)$/.test(s);
  let t = s.replace(/[()]/g, '').replace(/[^\d.,-]/g, '');
  if (t === '' || t === '-') return null;

  // Decide which separator is the decimal point by looking at the last one.
  const lastComma = t.lastIndexOf(',');
  const lastDot = t.lastIndexOf('.');
  if (lastComma > lastDot) {
    t = t.replace(/\./g, '').replace(',', '.');
  } else {
    t = t.replace(/,/g, '');
  }

  const n = Number(t);
  if (!Number.isFinite(n)) return null;
  return negative ? -n : n;
}

/** Inclusive window test on two 'YYYY-MM-DD' strings. String comparison is
 *  correct for ISO dates and avoids dragging a timezone into it. */
function inWindow(iso, start, end) {
  return iso !== null && iso >= start && iso <= end;
}

function daysBetween(fromIso, toIso) {
  if (!fromIso || !toIso) return null;
  const ms = Date.parse(toIso + 'T00:00:00Z') - Date.parse(fromIso + 'T00:00:00Z');
  return Math.round(ms / 86400000);
}

/** Division that refuses to invent a number. Returns null when the
 *  denominator is zero or missing -- an empty period must not read as 0%. */
function ratio(numerator, denominator) {
  if (denominator === null || denominator === undefined || Number(denominator) === 0) return null;
  return Number(numerator) / Number(denominator);
}

function mean(values) {
  const nums = values.filter((v) => typeof v === 'number' && Number.isFinite(v));
  if (nums.length === 0) return null;
  return nums.reduce((a, b) => a + b, 0) / nums.length;
}

function sum(values) {
  return values.reduce((a, b) => a + (typeof b === 'number' && Number.isFinite(b) ? b : 0), 0);
}

/** One metric row, shaped for the metrics table. Used ~30 times in the engine,
 *  so it is worth the four lines. */
function metric(domain, key, value, unit, denominator) {
  return {
    domain,
    metric_key: key,
    metric_value: (typeof value === 'number' && Number.isFinite(value)) ? value : null,
    metric_text: typeof value === 'string' ? value : null,
    unit,
    denominator: denominator === undefined ? null : denominator,
  };
}


// Node: "Grounding Check"  (Code, Run Once for All Items)
// Holds Claude's answer to the metrics it was actually given, for every period.
//
// One call now covers all periods, so this node takes one response and emits one
// insight row per period. Every item in every period must cite metric_keys drawn
// from the list supplied in the prompt; anything citing an unknown key, or
// citing nothing, is moved to ungrounded_claims and kept OUT of the report body.
// That converts "the insights are grounded" from a claim in a document into a
// number in a column.
//
// The LLM Chain node REPLACES json with its own output, so the allowed key list
// and the expected period list are recovered from Prepare Claude Input by name.

const ARRAY_FIELDS = ['risks_and_anomalies', 'recommended_actions'];
const SEVERITIES = ['high', 'medium', 'low'];

// Must match the model on the Anthropic Chat Model node. build.js asserts that
// these two agree, so they cannot drift apart silently.
const MODEL = 'claude-sonnet-5';

const context = $('Prepare Claude Input').first().json;
const allowed = new Set(context.allowed_metric_keys || []);
const expected = context.period_keys || [];

const raw = ($input.first() && $input.first().json) || {};
const answer = (raw.output && typeof raw.output === 'object') ? raw.output : raw;

// A whole-call failure. With one call covering every period, this loses all of
// them at once -- which is the price of the collapse. The node retries first,
// and every period still gets a row, so the dashboard degrades to "the insight
// step failed here" rather than going blank.
function failedRow(periodKey, message) {
  return {
    json: {
      run_id: context.run_id,
      period_key: periodKey,
      status: 'insight_failed',
      error_note: message,
      executive_summary: null,
      risks_and_anomalies: [],
      recommended_actions: [],
      data_quality_warnings: [],
      no_material_issues: null,
      ungrounded_claims: [],
      grounded_count: 0,
      ungrounded_count: 0,
      confidence: null,
      model: MODEL,
    },
  };
}

const out = [];

const periodsBack = Array.isArray(answer.periods) ? answer.periods : null;

if (raw.error || !periodsBack) {
  const rawError = raw.error;
  const message = typeof rawError === 'string'
    ? rawError
    : (rawError && rawError.message) || 'Model returned no periods array.';
  for (const key of expected) out.push(failedRow(key, message));
  return out;
}

const byKey = {};
for (const p of periodsBack) {
  if (p && p.period_key) byKey[p.period_key] = p;
}

for (const periodKey of expected) {
  const answerFor = byKey[periodKey];

  // The model returned some periods but not this one. That is this period's
  // failure, not the whole run's.
  if (!answerFor || !answerFor.executive_summary) {
    out.push(failedRow(periodKey, `The response contained no analysis for "${periodKey}".`));
    continue;
  }

  const clean = {};
  const ungrounded = [];
  let groundedCount = 0;

  for (const field of ARRAY_FIELDS) {
    const items = Array.isArray(answerFor[field]) ? answerFor[field] : [];
    const kept = [];

    for (const it of items) {
      const cited = Array.isArray(it.metric_keys) ? it.metric_keys : [];
      const unknown = cited.filter((k) => !allowed.has(k));

      if (cited.length === 0) {
        ungrounded.push({ field, item: it, reason: 'cites no metric at all' });
        continue;
      }
      if (unknown.length > 0) {
        ungrounded.push({ field, item: it, reason: `cites unknown metric(s): ${unknown.join(', ')}` });
        continue;
      }

      // Normalise the enums rather than trust free text to be one of three
      // words -- the dashboard sorts on these.
      if (field === 'risks_and_anomalies' && !SEVERITIES.includes(it.severity)) it.severity = 'low';
      if (field === 'recommended_actions' && !SEVERITIES.includes(it.priority)) it.priority = 'low';

      kept.push(it);
      groundedCount += 1;
    }

    clean[field] = kept;
  }

  // Data quality warnings are about the pipeline, not about a metric, so they
  // are not required to cite one and are never withheld.
  const warnings = Array.isArray(answerFor.data_quality_warnings)
    ? answerFor.data_quality_warnings : [];

  // Trust the model's all-clear flag, but do not let it claim nothing is wrong
  // while also reporting a high-severity risk.
  const declaredClear = answerFor.no_material_issues === true;
  const hasHighRisk = clean.risks_and_anomalies.some((r) => r.severity === 'high');

  out.push({
    json: {
      run_id: context.run_id,
      period_key: periodKey,
      status: 'ok',
      error_note: null,
      executive_summary: norm(answerFor.executive_summary),
      risks_and_anomalies: clean.risks_and_anomalies,
      recommended_actions: clean.recommended_actions,
      data_quality_warnings: warnings,
      no_material_issues: declaredClear && !hasHighRisk,
      ungrounded_claims: ungrounded,
      grounded_count: groundedCount,
      ungrounded_count: ungrounded.length,
      confidence: norm(answerFor.confidence),
      model: MODEL,
    },
  });
}

return out;
